# Zusammengesetzte Chat-Meldungen: Sie bestehen aus denselben Bausteinen wie
# im Code (chat_assistant_builder), damit Deutsch und Englisch synchron bleiben.
_SUPPORTED_CASES_EN = (
    "Right now I can calculate these three kinds of ordering decisions for "
    "**one product**:\n"
    "- **One-time order before a season** with uncertain demand and no "
    "reordering (e.g. Christmas trees, seasonal goods, daily newspapers)\n"
    "- **Regular reordering with steady, known demand** – how much per order "
    "(e.g. office supplies, consumables)\n"
    "- **Regular reordering with fluctuating demand** and continuous "
    "inventory monitoring – how much to order and at which stock level"
)


def _add_composite_messages() -> None:
    from agentic_optimization.ui import chat_assistant_builder as chat

    EN[chat.SUPPORTED_CASES_TEXT] = _SUPPORTED_CASES_EN
    EN[chat.UNSUPPORTED_MESSAGE] = (
        "**I unfortunately can't calculate this situation yet.**\n\n"
        "{reason}"
        + _SUPPORTED_CASES_EN
        + "\n\nIf your situation does fit one of these cases, feel free to "
        "describe it again with that focus. Otherwise you can start over "
        "with **Start new optimization**."
    )
    EN[chat.MISSING_DECISIVE_INFO_MESSAGE] = (
        "**Without this information I can't choose a suitable calculation "
        "model** – I don't want to guess here, because the recommendation "
        "could otherwise be wrong.\n\n"
        "You can add the missing information later: just tell me once you "
        "know it. "
        + _SUPPORTED_CASES_EN
    )


_add_composite_messages()

